import { ExprNode } from "groq-js";
import type { OpCall } from "groq-js";

/**
 * Parse a condition and derive its static structure: scope reads, the
 * boolean clause tree, and the flat atom list. Throws groq-js's syntax error
 * on an unparseable condition — analysis targets deployed definitions, whose
 * conditions parsed at deploy time.
 */
export declare function analyzeCondition(
  condition: Condition,
): ConditionAnalysis;

export declare interface AtomInsight {
  atom: ConditionAtom;
  /**
   * The atom's own three-valued verdict under GROQ's strict boolean
   * composition (a non-boolean operand of `&&`/`||`/`!` is GROQ `null`), with
   * the atom's negation applied. When the atom is the whole condition it
   * carries the engine's verdict directly — root truthiness coercion, and any
   * `!` wrappers GROQ strict-normalized, included — so it always matches the
   * condition's verdict.
   */
  outcome: ConditionOutcome;
  /**
   * Whether this atom currently decides the condition: forcing it satisfied —
   * holding every other atom at its actual verdict — would satisfy the whole
   * condition. Always `false` when the condition is already satisfied.
   */
  pivotal: boolean;
  /**
   * A requirement derived from the atom's expression, regardless of its current
   * outcome. Absent when no requirement can be derived. Use
   * {@link ConditionInsight.blockedBy} to find atoms that still block satisfaction.
   */
  requirement?: AtomRequirement;
}

/** Narrow an atom's opaque node — the unstable escape hatch pattern
 *  recognizers (`DescribeContext.atomPatterns`) need. Atoms are only ever
 *  built by {@link analyzeCondition}, which always stores the parsed groq-js
 *  expression here; the public type deliberately doesn't promise its shape. */
export declare function atomNode(atom: ConditionAtom): ExprNode;

/** Whether this atom's sub-expression reads the dataset (`*[...]` or a deref
 *  `->`) — the per-atom refinement of {@link ConditionAnalysis.readsDataset},
 *  so clause-level reasoning can tell which leg of a boolean tree depends on
 *  dataset state. Walks the stored {@link ConditionAtom.node}; the display
 *  `groq` string is not re-parsed (re-parsing can change meaning). */
export declare function atomReadsDataset(atom: ConditionAtom): boolean;

/**
 * What one scope read must satisfy for an atom to hold. A requirement can
 * describe a comparison with a literal, a presence check, or a bare read.
 * Atoms whose expressions cannot be expressed as requirements still appear
 * in {@link AtomInsight}; use their GROQ expressions for display.
 */
export declare type AtomRequirement =
  | {
      kind: "equals";
      target: ConditionRead;
      value: unknown;
    }
  | {
      kind: "differs";
      target: ConditionRead;
      value: unknown;
    }
  | {
      kind: "defined";
      target: ConditionRead;
    }
  | {
      kind: "undefined";
      target: ConditionRead;
    }
  | {
      kind: "truthy";
      target: ConditionRead;
    }
  | {
      kind: "falsy";
      target: ConditionRead;
    }
  | {
      kind: "compares";
      target: ConditionRead;
      op: ComparisonOp;
      value: unknown;
    };

/** Flatten a description to indented English lines — the CLI-friendly view
 *  of the checklist. Lines carry each item's ✓ / ✗ / ? outcome; pass
 *  `marks: false` for neutral bullets on no-instance (static) views, where
 *  GROQ's total equality yields real-looking `false` against an empty scope
 *  and a ✗ would read as a live judgment. */
export declare function checklistLines(
  description: ConditionDescription,
  options?: {
    marks?: boolean;
  },
): string[];

/** The GROQ binary operators that produce a comparison requirement. */
export declare const COMPARISON_OPS: readonly [
  "<",
  "<=",
  ">",
  ">=",
  "in",
  "match",
];

/** A GROQ binary operator that can be explained as a comparison requirement. */
export declare type ComparisonOp = (typeof COMPARISON_OPS)[number];

/** A GROQ expression evaluated as a boolean predicate; reads bind through `$`-prefixed params. */
export declare type Condition = string;

export declare interface ConditionAnalysis {
  condition: Condition;
  root: ConditionClause;
  /** Every atom in the clause tree, in source order. */
  atoms: ConditionAtom[];
  /** Deduped union of every atom's reads. */
  reads: ConditionRead[];
  /** The condition reads the dataset (`*[...]` or a deref `->`), so its
   *  verdict depends on snapshot hydration, not scope vars alone. */
  readsDataset: boolean;
}

/**
 * A leaf predicate after boolean decomposition — the unit "why is this
 * condition failing" reasoning works on. `And`/`Or`/`Not` structure is folded
 * into the {@link ConditionClause} tree (negation pushed down to the leaves,
 * so `!(a && b)` decomposes to `any` of two negated atoms); everything else
 * is an atom.
 */
export declare interface ConditionAtom {
  kind: "atom";
  /**
   * Canonical GROQ for display, via groq-js `unparse` (negation rendered as a
   * `!(...)` wrapper). Display-only: unparse collapses `['dotted.key']`
   * access to `.dotted.key`, so re-parsing this string can change meaning —
   * the insight machinery evaluates the opaque {@link ConditionAtom.node}.
   */
  groq: string;
  /** The condition needs this atom NOT to hold (it sat under a `!`). */
  negated: boolean;
  reads: ConditionRead[];
  /** The parsed sub-expression — deliberately opaque: the groq-js AST shape
   *  is not part of the public contract. Do not rely on its structure. */
  node: unknown;
}

export declare type ConditionClause =
  | {
      kind: "all";
      clauses: ConditionClause[];
    }
  | {
      kind: "any";
      clauses: ConditionClause[];
    }
  | ConditionAtom;

export declare interface ConditionDescription {
  /** English-only convenience: one line from the unmet frontier; absent when
   *  satisfied. i18n consumers compose their own from the checklist phrases. */
  summary?: string;
  /** The full checklist mirroring the clause tree. */
  checklist: DescribedClause;
  /** False when at least one leaf fell back to raw GROQ. */
  fullyDescribed: boolean;
}

export declare interface ConditionInsight {
  analysis: ConditionAnalysis;
  /** The condition's verdict, exactly as the engine computes it. */
  outcome: ConditionOutcome;
  atoms: AtomInsight[];
  /**
   * The unmet frontier as a clause tree — what still stands between the
   * current state and satisfaction: an unsatisfied `all` keeps its unmet
   * members, a failing `any` keeps every member (any one of those suffices).
   * Satisfied subtrees are pruned and a group left with one member collapses
   * to it, so the tree's connectives stay truthful after pruning. Absent when
   * the condition is satisfied.
   */
  frontier?: ConditionClause;
  /**
   * Every atom of {@link ConditionInsight.frontier} in source order — the
   * flat unmet frontier. Empty when the condition is satisfied. Which atoms
   * are single-fix sufficient is each entry's {@link AtomInsight.pivotal}.
   */
  blockedBy: AtomInsight[];
}

/**
 * A condition's result. A final `null` or `undefined` is `'unevaluable'`.
 * Other values use JavaScript truthiness: truthy values are `'satisfied'`;
 * falsy values are `'unsatisfied'`.
 *
 * A missing parameter does not always produce `'unevaluable'`. With no
 * `$approved` value, `$approved == true` is `'unsatisfied'`, while
 * `$approved != true` and `$approved == null` are `'satisfied'`.
 */
export declare type ConditionOutcome =
  | "satisfied"
  | "unsatisfied"
  | "unevaluable";

/**
 * Map a raw GROQ result to the three-valued {@link ConditionOutcome}: GROQ
 * `null`/`undefined` is `'unevaluable'`, anything else resolves by
 * truthiness. The one place that coercion lives.
 */
export declare function conditionOutcome(result: unknown): ConditionOutcome;

/**
 * One scope-var read discovered in a condition, e.g. `$fields.legalApproved`
 * as `{variable: 'fields', path: ['legalApproved']}`. Variable names are
 * whatever `$params` the host binds; a bracket access with a dotted key
 * (`$effectStatus['notify.legal']`) stays one path segment.
 */
export declare interface ConditionRead {
  variable: string;
  path: (string | number)[];
}

/** Order-preserving dedupe by a derived string key — first occurrence wins. */
export declare function dedupeBy<T>(
  items: readonly T[],
  keyOf: (item: T) => string,
): T[];

/** Order-preserving dedupe of reads by their structural identity. */
export declare function dedupeReads(
  reads: readonly ConditionRead[],
): ConditionRead[];

/** One atom as a phrase: its requirement when solvable, a shape-pattern
 *  match when recognizable (host patterns first), otherwise the GROQ
 *  fallback with a reads hint. */
export declare function describeAtom(
  atom: AtomInsight,
  ctx: DescribeContext,
): {
  phrase: InsightPhrase;
  fallback: boolean;
};

/** Render one condition's insight as a checklist + frontier summary. */
export declare function describeCondition(
  insight: ConditionInsight,
  ctx: DescribeContext,
): ConditionDescription;

/**
 * Rendering seams — how a host wires its own vocabulary and dialect into the
 * generic templates. Everything is optional; with an empty context the
 * renderer still phrases every solvable shape, just with `$var` spellings.
 */
export declare interface DescribeContext {
  /** First-chance read rendering (field titles, var labels); `undefined`
   *  falls through to the generic `$var (path)` spelling. */
  renderRead?: ((read: ConditionRead) => InsightPhrase | undefined) | undefined;
  /** First-chance whole-requirement phrasing (domain specials); `undefined`
   *  falls through to the requirement templates. */
  renderRequirement?:
    | ((requirement: AtomRequirement) => InsightPhrase | undefined)
    | undefined;
  /** Extra atom recognizers tried BEFORE the built-ins — the host's
   *  canonical desugar shapes. */
  atomPatterns?:
    | readonly ((
        atom: ConditionAtom,
        ctx: DescribeContext,
      ) => InsightPhrase | undefined)[]
    | undefined;
  /** Param name whose ordered comparisons phrase as past/future
   *  (`$now`-style clock reads); temporal phrasing is off when absent. */
  nowParam?: string | undefined;
}

export declare type DescribedClause =
  | {
      kind: "group";
      op: "all" | "any";
      label: InsightPhrase;
      items: DescribedClause[];
    }
  | {
      kind: "item";
      phrase: InsightPhrase;
      outcome: ConditionOutcome;
      fallback: boolean;
      groq: string;
    };

/** A scope read as a noun phrase: the host's vocabulary first, then the
 *  generic `$var (path)` spelling. */
export declare function describeRead(
  read: ConditionRead,
  ctx: DescribeContext,
): InsightPhrase;

export declare interface EvaluateConditionArgs {
  condition: string | undefined;
  dataset: unknown[];
  params: Record<string, unknown>;
}

/** Evaluate a condition to its {@link ConditionOutcome}; an absent condition
 *  is vacuously `'satisfied'` (an ungated site). */
export declare function evaluateConditionOutcome(
  args: EvaluateConditionArgs,
): Promise<ConditionOutcome>;

/**
 * Keeps a literal option list exhaustive over `TOption` while preserving its
 * literal members.
 *
 * This helper is exported only so Workflows packages can share the same
 * compile-time contract. It is unsupported implementation infrastructure, not
 * part of the package's public GROQ-description API.
 *
 * @internal
 */
export declare function _exhaustiveOptions<TOption>(): <
  const TOptions extends readonly TOption[],
>(
  options: TOptions,
  ..._missing: Exclude<TOption, TOptions[number]> extends never
    ? []
    : [missing: never]
) => TOptions;

/** Explain one condition against a rendered scope: overall verdict, per-atom
 *  verdicts, pivotality, and derivable requirements. */
export declare function explainCondition(
  args: ExplainConditionArgs,
): Promise<ConditionInsight>;

export declare interface ExplainConditionArgs {
  condition: Condition;
  dataset: unknown[];
  params: Record<string, unknown>;
}

/** Render a read back as its scope spelling, e.g. `$fields.legalApproved`
 *  (bracket form for segments that aren't plain identifiers). */
export declare function formatRead(read: ConditionRead): string;

/** A value as display text: strings quoted, arrays joined, `null` spelled. */
export declare function formatValue(value: unknown): string;

/**
 * @internal The grammar an attribute name must match to be spliced into GROQ as
 * a bare `.name` access on a base. A name outside it needs bracket-quoting, and
 * one like `review-owner` would otherwise parse as subtraction. Shared with
 * `@sanity/workflow-engine`; not a supported consumer API.
 */
export declare const _GROQ_ATTRIBUTE_NAME: RegExp;

/** A title as «guillemet» display text, embedded guillemets escaped —
 *  {@link quoted}'s twin for the field-title delimiter. */
export declare function guillemets(title: string): string;

/** camelCase / kebab-case / snake_case → space-separated words, label-cased
 *  ("legalApproved" → "Legal approved"). Derived names only — authored titles
 *  render verbatim. */
export declare function humanize(name: string): string;

/**
 * One rendered phrase. `id` is a stable, namespaced message id and `params`
 * its interpolation values (raw leaves like titles/values/names, plus
 * pre-rendered sub-phrases in the default locale); `text` is the English
 * default. i18n consumers translate by id and interpolate params themselves.
 */
export declare interface InsightPhrase {
  id: string;
  params: Record<string, unknown>;
  text: string;
}

/** @internal Whether `name` can open a GROQ path spliced with no base, as
 *  `name` rather than `$var.name`. In that position GROQ reads `true`, `false`
 *  and `null` as its own literals, so the grammar alone is not enough. Shared
 *  with `@sanity/workflow-engine`; not a supported consumer API. */
export declare function _isBareLeadingAttributeName(name: string): boolean;

export declare function isComparisonOp(op: OpCall): op is ComparisonOp;

/** Join items with an "and" tail: "a, b and c". */
export declare function listAnd(items: string[]): string;

/** Join items with an "or" tail: "a, b or c". */
export declare function listOr(items: string[]): string;

/**
 * Largest nonnegative array index accepted by {@link withAssignment} and
 * {@link whatIfCondition}, including when the target array already exists.
 */
export declare const MAX_COUNTERFACTUAL_INDEX = 1000;

/** The neutral bullet a no-instance (static) checklist carries in place of a
 *  verdict, where a ✗ would read as a live judgment. */
export declare const NEUTRAL_MARK = "\u2022";

/** The verdict glyph per outcome — one vocabulary for every checklist
 *  rendering, flat lines ({@link checklistLines}) and structured alike. */
export declare const OUTCOME_MARKS: Record<ConditionOutcome, string>;

/** Build an {@link InsightPhrase} under the shared namespace — the one
 *  constructor hosts and built-ins alike use, so the catalog stays coherent. */
export declare function phrase(
  id: string,
  body: {
    params: Record<string, unknown>;
    text: string;
  },
): InsightPhrase;

/** A name/title as `"quoted"` display text, embedded quotes escaped — the
 *  delimiters are the only data-vs-prose signal, so a name must not be able
 *  to close them. */
export declare function quoted(name: string): string;

/**
 * @internal Whether `node` resolves against documents other than the one in
 * scope: a dataset scan (`*[…]`) or a dereference (`->`), at `node` itself or
 * at any depth below it. Takes a groq-js AST node, whose shape this package does not treat as a
 * public contract. Shared with `@sanity/workflow-engine`, which asks it of a
 * parsed root; not a supported consumer API.
 */
export declare function _readsDataset(node: ExprNode): boolean;

/** Evaluate one GROQ expression against the dataset. The dataset is ALWAYS
 *  bound — a pure-param expression ignores it, `->` derefs and `*[...]`
 *  joins need it. */
export declare function runGroq({
  groq,
  params,
  dataset,
}: {
  groq: string;
  params: Record<string, unknown>;
  dataset: unknown[];
}): Promise<unknown>;

/**
 * Evaluate an already-parsed GROQ expression — the node-level half of
 * {@link runGroq}. Decomposed sub-expressions evaluate through here: a
 * params-free parse keeps `Parameter` nodes in the tree (parsing with params
 * inlines them as values), and the evaluator resolves those from `params`
 * identically.
 */
export declare function runGroqNode({
  tree,
  params,
  dataset,
}: {
  tree: ExprNode;
  params: Record<string, unknown>;
  dataset: unknown[];
}): Promise<unknown>;

export declare interface ScopeAssignment {
  target: ConditionRead;
  value: unknown;
}

/**
 * The scope-var access chain a node spells, if it is one: a `Parameter` root
 * with any run of attribute/element accesses on top (`$fields.doc.title`,
 * `$activities[0].status`). Group wrapping is transparent. `undefined` for
 * anything else — including chains crossing a deref, whose tail lives on a
 * dataset document rather than the scope.
 */
export declare function scopeReadOf(node: ExprNode): ConditionRead | undefined;

/**
 * Uppercase a phrase's first letter for standalone display (checklist lines,
 * tooltips). Phrase `.text` is deliberately lowercase so it composes
 * mid-sentence; apply this at sentence boundaries. A quoted-name lead
 * («…», "…") is left alone — names render as authored.
 */
export declare function sentenceCase(text: string): string;

/**
 * Re-evaluate a condition with one scope value replaced, such as
 * `$fields.approved` set to `true`. The original params are unchanged.
 * Assignment follows {@link withAssignment}: missing containers are created,
 * and negative indices count from the end of an existing array.
 *
 * @throws If an index exceeds {@link MAX_COUNTERFACTUAL_INDEX}, or a negative
 * index resolves before the start of its array.
 */
export declare function whatIfCondition(
  args: ExplainConditionArgs & {
    assign: ScopeAssignment;
  },
): Promise<WhatIfOutcome>;

export declare interface WhatIfOutcome {
  before: ConditionOutcome;
  after: ConditionOutcome;
  changed: boolean;
}

/**
 * Return a copy of the params with one scope read replaced. The original
 * params are unchanged; containers along the assignment path are copied or
 * created when missing.
 *
 * Negative indices count from the end of the existing array. For example,
 * `-1` replaces its last element and cannot be assigned in an empty array.
 *
 * @throws If an index exceeds {@link MAX_COUNTERFACTUAL_INDEX}, or a negative
 * index resolves before the start of its array.
 */
export declare function withAssignment(
  params: Record<string, unknown>,
  { target, value }: ScopeAssignment,
): Record<string, unknown>;

export {};
